163	function ReportResultDialog({ gameId, isCreator, result, sport }: {
164	  gameId: number; isCreator: boolean; result?: GameResult; sport: string;
165	}) {
166	  const { toast } = useToast();
167	  const qc = useQueryClient();
168	  const [open, setOpen] = useState(false);
169	  const [score, setScore] = useState<SportScore | null>(null);
170	  const [valid, setValid] = useState(false);
171	
172	  const winnerSide = score && valid ? deriveWinner(score, getSportConfig(sport)) : null;
173	
174	  const report = useMutation({
175	    mutationFn: () => customFetch(`${API}/games/${gameId}/result`, {
176	      method: "POST", headers: { "Content-Type": "application/json" },
177	      body: JSON.stringify({ score }),
178	    }),
179	    onSuccess: () => {
180	      qc.invalidateQueries({ queryKey: ["game", gameId] });
181	      qc.invalidateQueries({ queryKey: ["game-result", gameId] });
182	      toast({ title: "Rezultatas paskelbtas!", description: "Dalyviai gali patvirtinti per 24h." });
183	      setOpen(false);
184	      setScore(null);
185	      setValid(false);
186	    },
187	    onError: (e: any) => toast({ title: "Klaida", description: e?.message, variant: "destructive" }),
188	  });
189	
190	  if (result) {
191	    const statusMap: Record<string, { label: string; cls: string }> = {
192	      pending_verification: { label: "Laukiama patvirtinimo", cls: "bg-yellow-500/15 text-yellow-500 border-yellow-400/30" },
193	      confirmed: { label: "Patvirtinta", cls: "bg-green-500/15 text-green-500 border-green-400/30" },
194	      disputed: { label: "Ginčijama", cls: "bg-red-500/15 text-red-500 border-red-400/30" },
195	    };
196	    const s = statusMap[result.status] ?? { label: result.status, cls: "" };
197	    return (
198	      <div className="rounded-2xl border border-border bg-card p-5 sm:p-6 space-y-3">
199	        <div className="flex items-center gap-2">
200	          <Trophy className="w-5 h-5 text-primary" />
201	          <h2 className="font-bold text-lg">Rezultatas</h2>
202	          <span className={`ml-auto px-2.5 py-0.5 rounded-full text-xs font-semibold border ${s.cls}`}>{s.label}</span>
203	        </div>
204	        <div className="flex items-center justify-center gap-6 py-4 bg-muted/30 rounded-xl">
205	          <div className="text-center">
206	            <div className="text-xs text-muted-foreground mb-1">Komanda A</div>
207	            <div className="text-4xl font-black text-primary">{result.scoreTeamA}</div>
208	          </div>
209	          <div className="text-2xl font-bold text-muted-foreground">:</div>
210	          <div className="text-center">
211	            <div className="text-xs text-muted-foreground mb-1">Komanda B</div>
212	            <div className="text-4xl font-black text-primary">{result.scoreTeamB}</div>
213	          </div>
214	        </div>
215	        {result.autoConfirmAt && result.status === "pending_verification" && (
216	          <p className="text-xs text-muted-foreground text-center">
217	            Auto-patvirtinimas: {new Date(result.autoConfirmAt).toLocaleString("lt-LT")}
218	          </p>
219	        )}
220	      </div>
221	    );
222	  }
223	
224	  if (!isCreator) return null;
225	
226	  return (
227	    <Dialog open={open} onOpenChange={setOpen}>
228	      <DialogTrigger asChild>
229	        <Button className="bg-primary text-primary-foreground hover:bg-primary/90 gap-2">
230	          <Trophy className="w-4 h-4" />Paskelbti rezultatą
231	        </Button>
232	      </DialogTrigger>
233	      <DialogContent className="max-w-sm">
234	        <DialogHeader>
235	          <DialogTitle>Paskelbti žaidimo rezultatą</DialogTitle>
236	          <DialogDescription>Dalyviai gaus pranešimą ir turės 24h patvirtinti.</DialogDescription>
237	        </DialogHeader>
238	        <div className="py-2">
239	          <SportScoreInput
240	            sport={sport}
241	            labelA="Komanda A"
242	            labelB="Komanda B"
243	            value={score}
244	            onChange={(s, v) => { setScore(s); setValid(v); }}
245	            showErrors
246	            disabled={report.isPending}
247	          />
248	          {score && valid && !winnerSide && (
249	            <p className="mt-3 text-xs text-destructive">Lygiosios negalimos – pakoreguokite rezultatą.</p>
250	          )}
251	          {winnerSide && (
252	            <p className="mt-3 text-xs text-muted-foreground">
253	              Nugalėtoja: <span className="font-semibold text-foreground">Komanda {winnerSide === "a" ? "A" : "B"}</span>
254	            </p>
255	          )}
256	        </div>
257	        <DialogFooter>
258	          <Button variant="outline" onClick={() => setOpen(false)}>Atšaukti</Button>
259	          <Button onClick={() => report.mutate()} disabled={!score || !valid || !winnerSide || report.isPending}>
260	            {report.isPending ? "Skelbiama..." : "Paskelbti"}
261	          </Button>
262	        </DialogFooter>
263	      </DialogContent>
264	    </Dialog>
265	  );
266	}
