315	function InviteSection({ gameId }: { gameId: number }) {
316	  const { toast } = useToast();
317	  const [email, setEmail] = useState("");
318	  const [name, setName] = useState("");
319	  const [open, setOpen] = useState(false);
320	
321	  const invite = useMutation({
322	    mutationFn: () => {
323	      const emailErr = validateEmail(email);
324	      if (emailErr) throw new Error(emailErr);
325	      return customFetch(`${API}/games/${gameId}/invite`, {
326	        method: "POST", headers: { "Content-Type": "application/json" },
327	        body: JSON.stringify({ email: email.trim(), name: name || undefined }),
328	      });
329	    },
330	    onSuccess: () => {
331	      toast({ title: "Kvietimas išsiųstas!", description: `El. laiškas išsiųstas ${email}` });
332	      setEmail(""); setName(""); setOpen(false);
333	    },
334	    onError: (e: any) => toast({ title: "Klaida", description: e?.message, variant: "destructive" }),
335	  });
336	
337	  return (
338	    <Dialog open={open} onOpenChange={setOpen}>
339	      <DialogTrigger asChild>
340	        <Button variant="outline" size="sm" className="gap-1.5">
341	          <Mail className="w-4 h-4" />Pakviesti el. paštu
342	        </Button>
343	      </DialogTrigger>
344	      <DialogContent className="max-w-sm">
345	        <DialogHeader>
346	          <DialogTitle>Pakviesti žaidėją</DialogTitle>
347	          <DialogDescription>Išsiųsime kvietimą el. paštu su nuoroda prisijungti.</DialogDescription>
348	        </DialogHeader>
349	        <div className="space-y-3 py-2">
350	          <div>
351	            <Label>El. paštas *</Label>
352	            <Input className="mt-1" type="email" placeholder="draugas@example.com" value={email} onChange={e => setEmail(e.target.value)} />
353	          </div>
354	          <div>
355	            <Label>Vardas (neprivaloma)</Label>
356	            <Input className="mt-1" placeholder="Jonas" value={name} onChange={e => setName(e.target.value)} />
357	          </div>
358	        </div>
359	        <DialogFooter>
360	          <Button variant="outline" onClick={() => setOpen(false)}>Atšaukti</Button>
361	          <Button onClick={() => invite.mutate()} disabled={invite.isPending || !email}>
362	            <Send className="w-4 h-4 mr-1.5" />
363	            {invite.isPending ? "Siunčiama..." : "Siųsti kvietimą"}
364	          </Button>
365	        </DialogFooter>
366	      </DialogContent>
367	    </Dialog>
368	  );
369	}
