496	export default function GameDetailPage() {
497	  const params = useParams<{ id: string }>();
498	  const [, setLocation] = useLocation();
499	  const { user } = useUser();
500	  const { toast } = useToast();
501	  const qc = useQueryClient();
502	  const id = parseInt(params.id!, 10);
503	  const token = new URLSearchParams(window.location.search).get("token") ?? "";
504	
505	  const { data, isLoading, error } = useQuery<GameDetail>({
506	    queryKey: ["game", id, token],
507	    queryFn: () => customFetch<GameDetail>(`${API}/games/${id}${token ? `?token=${token}` : ""}`),
508	    enabled: !isNaN(id),
