122	// GET /games/my — games where I'm creator or participant (game history)
123	router.get("/games/my", requireAuth, async (req, res): Promise<void> => {
124	  const userId = getCurrentUserId(req)!;
125	
126	  // Games where user is a participant (joined) — targeted query
127	  const participantRows = await db
128	    .select({ gameId: gameParticipantsTable.gameId, team: gameParticipantsTable.team })
129	    .from(gameParticipantsTable)
130	    .where(and(eq(gameParticipantsTable.userId, userId), eq(gameParticipantsTable.status, "joined")));
131	  const participantGameIds = participantRows.map(r => r.gameId);
132	  const myTeamMap = new Map(participantRows.map(r => [r.gameId, r.team]));
133	
134	  // Fetch only games where user is creator OR participant — no full table scan
135	  const games = participantGameIds.length > 0
136	    ? await db.select().from(gamesTable)
137	        .where(or(eq(gamesTable.creatorUserId, userId), inArray(gamesTable.id, participantGameIds)))
138	        .orderBy(desc(gamesTable.datetime))
139	    : await db.select().from(gamesTable)
140	        .where(eq(gamesTable.creatorUserId, userId))
141	        .orderBy(desc(gamesTable.datetime));
142	
143	  if (games.length === 0) { res.json([]); return; }
144	
145	  const gameIds = games.map(g => g.id);
146	
147	  // Get participants only for these specific games
148	  const allParticipants = await db
149	    .select()
150	    .from(gameParticipantsTable)
151	    .where(and(inArray(gameParticipantsTable.gameId, gameIds), eq(gameParticipantsTable.status, "joined")));
152	  const participantsByGame = new Map<number, typeof allParticipants>();
153	  for (const p of allParticipants) {
154	    if (!participantsByGame.has(p.gameId)) participantsByGame.set(p.gameId, []);
155	    participantsByGame.get(p.gameId)!.push(p);
156	  }
157	
158	  // Get results only for these specific games
159	  const results = await db.select().from(gameResultsTable)
160	    .where(inArray(gameResultsTable.gameId, gameIds));
161	  const resultByGame = new Map(results.map(r => [r.gameId, r]));
